#pragma once
/* Player-facing explanations. Keep implementation evidence out of this text. */
static const char *GameplayExplanation(const char *id) {
    const char *key=strrchr(id,'.');key=key?key+1:id;
    struct Help {const char *key,*text;};
    static const Help help[]={
      {"camera","Choose how the camera follows Simba, including how far it looks ahead while moving and riding the ostrich."},
      {"life_pickup_limit","Choose the maximum number of spare lives: SNES allows eight; Genesis allows nine. This also affects when another 1UP can appear."},
      {"adult_turn_motion","SNES shifts adult Simba slightly while he turns around. Genesis has him turn in place."},
      {"roar","Choose how quickly cub Simba starts his roar and how the roar animation plays."},
      {"adult_roar","Choose the timing of adult Simba's roar. You can choose its sound separately."},
      {"adult_ledge_reactions","Choose how adult Simba lets go of ledges and reacts to enemies while hanging."},
      {"adult_points","Choose how adult Simba's hands and attacks reach ledges, walls and obstacles."},
      {"simba","Choose how close Simba must be to an enemy or hazard before a touch counts."},
      {"enemies","Choose how close Simba must get before touching an enemy counts as contact."},
      {"contacts","Choose the shapes of solid ground, walls, slopes and ledges from each version."},
      {"terrain","Choose the solid ground, slopes, walls and ledges from each version. Scenery artwork is a separate choice."},
      {"start","Choose where the player starts this level. An activated checkpoint still decides where a retry begins."},
      {"activation","Choose when nearby enemies first become active as the level begins."},
      {"lizard_reactivation","Genesis brings an offscreen lizard back from where it was last seen; SNES uses its original starting spot."},
      {"streaming_top","Choose how early enemies above the screen wake up as the camera approaches them."},
      {"ceiling_rows","Choose how Simba's jumps react to the underside of platforms and low ceilings."},
      {"ceiling_clearance","Choose how much room Simba needs above his head before a ceiling stops his jump."},
      {"adult_ceiling_rows","Choose how adult Simba's jumps react to low ceilings and overhangs."},
      {"ledge_wall_probes","Genesis lets Simba clear some ledge corners when jumping sideways that can block him with the SNES setting. Where his hands catch the ledge is a separate choice."},
      {"grip_points","Choose where Simba's hands catch a ledge when he jumps towards it."},
      {"health_death","Choose how defeated Simba moves towards the middle of the screen. Choose his sprite drawings and colors separately under Artwork."},
      {"final_life","Choose the transition to Continue or Game Over when no spare lives remain."},
      {"random_entry","Choose the starting pattern of random enemy actions when entering or continuing this level."},
      {"scene_random_state","Choose how random enemy patterns carry over when moving between stages."},
      {"hyena_probe_height","SNES checks for walls near the hyena's feet. Genesis checks slightly higher, so low changes in the ground are less likely to make it turn around."},
      {"hyena_entrance_window","Genesis starts the hyena's entrance countdown from farther offscreen, so the fight is ready sooner as Simba approaches. SNES waits until the camera is closer."},
      {"hyena_ground_tags","Choose where the hyenas turn and how they approach Simba before jumping."},
      {"hyena_wall_probes","SNES checks for walls at the hyena's feet. Genesis checks slightly higher, letting it pass the foot of a slope instead of turning back there. This changes where it approaches Simba and jumps."},
      {"vulture_health","Genesis patrolling vultures take one fewer hit than their SNES counterparts."},
      {"vulture_turn_point","Genesis puts the flying vulture's turn-back point farther to the right of the screen than SNES. This changes how long it can follow Simba before turning."},
      {"vulture_launch_timing","SNES begins a perched vulture's take-off immediately. Genesis can add a brief wait before it starts. Its flight path and health are separate choices."},
      {"falling_bone_shake","SNES makes loose bones shake from side to side before falling. Genesis makes them jitter up and down."},
      {"falling_bone_support","Choose how a loose bone reacts when Simba lands on it again."},
      {"bone_contact","Choose where Simba's feet land on a moving bone platform."},
      {"mufasa_farewell","Choose the length and timing of Scar's farewell at the end of the Graveyard."},
      {"gorilla_recovery","After a normal landing, the Genesis gorilla rests for about a fifth of a second; the SNES gorilla rests for about a second. The final landing pause is the same in both."},
      {"gorilla_defeat_pauses","SNES holds the first part of the gorilla's defeat longer, then moves through the later pause faster. Genesis has a shorter first hold and a longer later pause."},
      {"gorilla_initialization","Choose when the gorilla begins its first action after appearing."},
      {"coconut_lifetime","Genesis keeps thrown coconuts active farther to the right beyond the camera than SNES, so they can still enter the wider view. Their movement and bounces stay the same."},
      {"log_continuity","Choose how floating logs begin and reset when they enter the screen."},
      {"spider_initialization","Choose when a newly appearing spider begins moving and attacking."},
      {"monkey_behavior","Choose how Destiny monkeys move, fire projectiles and react to obstacles."},
      {"arena_barrier","Choose the boundary around the panther battle arena."},
      {"boulder_surface","Choose where Simba can stand on top of a stationary boulder."},
      {"boulder_contact","Choose how Simba touches or is blocked by a stationary boulder."},
      {"leaper_behavior","Choose how the jumping enemies wake up, follow each other and move as a group."},
      {"attack_events","Choose how the jumping enemies progress through an attack."},
      {"lava_spread","Choose how widely lava droplets scatter sideways."},
      {"geyser_initialization","Choose when lava geysers begin their first eruption."},
      {"death_update_order","Choose how the scene finishes its current action when Simba dies in lava."},
      {"fatal_contact_handling","Choose when a fatal hit starts the death sequence while other creatures are still acting."},
      {"retry_controls","Choose the brief wait before movement controls work after a retry."},
      {"entry_input_delay","Choose the brief wait before Simba can move at the start of the level."},
      {"entry_input_filter","Choose which direction buttons are accepted while the opening scene holds Simba still."},
      {"opening_skull_trigger","Choose how close Simba must get before the opening skull reveals its hyenas."},
      {"control_handoff","SNES lets you move sooner after Simba leaves his crouch during the skull reveal. Genesis keeps the remaining opening wait before returning control."},
      {"doorway_hyenas","Choose which hyenas appear after entering each cave. Some Genesis rooms contain an extra hyena."},
      {"doorway_timing","Choose the pause when Simba enters a cave before play resumes inside."},
      {"exit_timing","Choose the wait after clearing the final room before the level ends."},
      {"exit_boundary","Choose how far Simba must go at the end before the level is complete."},
      {"exit_start_skip","Choose whether Start can skip the level's closing scene."},
      {"outro_holds","Choose how long the final poses in the closing scene stay on screen."},
      {"scar_contact_response","Choose how Simba and Scar push apart after touching."},
      {"scar_activation","Choose when Scar becomes active and is revealed as you approach the next fight."},
      {"adult_culling","Choose when an adult hyena disappears after leaving the visible part of a level."},
      {"rain","Choose how the ending rain builds up and travels across the screen after Scar's defeat."},
      {"ending_timing","Choose the pauses and progression from Scar's defeat into the ending."},
      {"interlevel_scene","Choose the SNES or Genesis illustrated scene after Pride Lands, including its timing and skip behavior."},
      {"exit_flow","Choose the closing sequence after escaping the stampede."},
      {"movement_bounds","During the stampede, SNES lets Simba move slightly farther to the left. Genesis stops him a little earlier. The right-hand limit and running speed are the same."},
      {"obstacle_lanes","Choose the lanes used by obstacles during the stampede."},
      {"damage","Choose how much health Simba loses when hit during the stampede."},
      {"rock_contacts","Choose when a stampede rock is close enough to hit Simba."},
      {"rock_perspective","Choose how widely approaching Stampede rocks spread to the sides, including where they can touch Simba."},
      {"running_timing","Choose how Simba starts his running animation during the stampede."},
      {"camera_shake","Choose how the camera shake settles when returning from a bonus round."},
      {"hippo_height","Choose the height at which Simba can stand on a hippo."},
      {"giraffe_platforms","Choose where Simba's feet land when he stands or jumps on a giraffe's head."},
      {"ostrich_obstacles","Choose the order and placement of obstacles in the ostrich rides."},
      {"rhino_tail_bounds","Choose where Simba's hands can catch the rhino's tail."},
      {"sunrise_timing","SNES changes the scenery colours at once when Simba leaves the starting branch. Genesis blends them gradually. Choose the colours themselves under Artwork; sprite colours stay separate."},
      {"monkey_roar_range","Genesis lets Simba's roar reach monkeys slightly farther away, both sideways and above or below him. SNES requires him to be closer."},
      {"monkey_grips","Choose where the monkeys hold Simba and release him when throwing him."},
      {"porcupine_attack","Choose when a porcupine's attack can hurt Simba."},
      {"pickup_flight","Choose the path collected pickups follow as they fly towards the top of the screen."},
      {"continue_token_animation","Choose how quickly the sun-shaped Continue token spins in every level. Genesis spins slightly more slowly than SNES. Its artwork, colours, placement, sound and reward are separate."},
      {"checkpoint_animation","Choose how the checkpoint head blinks after Simba activates it."},
      {"leaves","Choose how many leaves fall together and how quickly they drift down."},
      {"culling_bounds","Choose how far beyond the screen a creature or falling bug remains active."},
      {"draw_bounds","Choose how far towards the screen edges bugs remain visible."},
      {"arena","Choose how far Pumbaa can move sideways to catch falling bugs."},
      {"reward_eligibility","Choose when extra-life, health and Continue bugs are allowed to appear."},
      {"result_flow","Choose how the bonus-round result and rewards are presented."},
      {"round_selection","Choose which bonus round follows each main level."},
      {"clock_start","Choose when the bonus countdown begins after the round opens."},
      {"timer","Choose the bonus round's countdown and when the round ends."},
      {"rewards","Genesis alternates an extra life and a Continue for every ten bugs. SNES can also award a health upgrade after forty."},
      {"movement_profile","Choose how Timon moves and jumps while collecting bugs."},
      {"title_navigation","Choose the title menu's button response and how Start and Options are selected."},
      {"options_navigation","Choose how the Options menu wraps, changes values and exits."}
    };
    for(const auto &h:help)if(!strcmp(key,h.key))return h.text;
    if(strstr(key,"positions")||strstr(key,"placements")||strstr(key,"position")||!strcmp(key,"pickups"))return "Choose the original locations of these objects in this level. Their appearance and sounds can be chosen separately.";
    if(strstr(key,"bounds")||strstr(key,"contact")||!strcmp(key,"bug_bounds"))return "Choose how close the player and this object must be before touching, landing or taking damage counts.";
    return "Choose the original SNES or Genesis rules for this part of the game. Open a child choice to see what it changes.";
}
